  `)}function $e(e){return He("SELECT * FROM projetos WHERE id = ?",[e])}var JR=["p.id","p.nome","p.responsavel_nome","p.responsavel_email","p.area","p.ferramenta","p.escopo","p.status","p.tipos_projeto","p.descricao_breve","p.complexidade","p.chat_completo","p.created_at","p.updated_at","p.submitted_at"].join(", ");function Ug(){return xe(`
